// Verify the request, drop duplicates, and compose the messages.
// Needs env: ACADEMY_SIGNING_SECRET, NODE_FUNCTION_ALLOW_BUILTIN=crypto, N8N_BLOCK_ENV_ACCESS_IN_NODE=false
const crypto = require('crypto');
const { headers = {}, body } = $input.first().json;
const secret = $env.ACADEMY_SIGNING_SECRET;

// 1) Signature over "<timestamp>.<body>" (the app signs compact JSON; parse+stringify round-trips it exactly)
const ts = Number(headers['x-academy-timestamp']);
const expected = 'sha256=' + crypto.createHmac('sha256', secret || '').update(`${ts}.${JSON.stringify(body)}`).digest('hex');
const given = String(headers['x-academy-signature'] || '');
const signatureOk = Boolean(secret) && given.length === expected.length
  && crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected));
const fresh = Number.isFinite(ts) && Math.abs(Date.now() / 1000 - ts) < 300;
if (!signatureOk || !fresh) {
  return [{ json: { status: 'invalid', reason: signatureOk ? 'stale timestamp' : 'bad signature' } }];
}

// 2) De-duplicate on dedupeKey (the app delivers at least once). Kept 30 days.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
for (const [key, at] of Object.entries(store.seen)) if (now - at > 30 * 86400000) delete store.seen[key];
if (store.seen[body.dedupeKey]) return [{ json: { status: 'duplicate', dedupeKey: body.dedupeKey } }];
store.seen[body.dedupeKey] = now;

// 3) Compose
const s = body.student;
const tz = s.timezone || 'UTC';
const name = s.firstName ? ` ${s.firstName}` : '';
const date = (iso) => iso ? new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', timeZone: tz }) : '';
const p = body.payload || {};
const L = body.links;

const copy = {
  'student.enrolled': {
    subject: 'Welcome to Demo Academy',
    lines: [`Assalāmu ʿalaykum${name},`, 'Your access is ready. The best time to begin is today: your first lesson takes about ten minutes.'],
    cta: ['Start lesson 1', L.dashboard],
  },
  'student.inactive_3d': {
    subject: 'Your first lesson is waiting',
    lines: [`Assalāmu ʿalaykum${name},`, "You joined a few days ago but haven't started yet. Ten minutes today is a good beginning, in shā' Allāh."],
    cta: ['Open my programmes', L.dashboard],
  },
  'payment.failed': {
    subject: "Your payment didn't go through",
    lines: [`Assalāmu ʿalaykum${name},`, `We couldn't take your last payment. Your access continues until ${date(p.graceUntil)}.`, "Please update your card and we'll retry automatically."],
    cta: ['Update my card', L.billing],
  },
  'payment.recovered': {
    subject: 'Payment received, thank you',
    lines: [`Assalāmu ʿalaykum${name},`, 'Your payment went through and your access is back to normal. Bārak Allāhu fīk.'],
    cta: ['Continue learning', L.dashboard],
  },
  'subscription.cancel_scheduled': {
    subject: `Your plan will end on ${date(p.endsAt)}`,
    lines: [`Assalāmu ʿalaykum${name},`, `Your plan is cancelled and you keep access until ${date(p.endsAt)}. Changed your mind? You can keep it with one click.`],
    cta: ['Keep my plan', L.billing],
  },
  'subscription.ended': {
    subject: 'Your plan has ended',
    lines: [`Assalāmu ʿalaykum${name},`, 'Your plan has ended. Your progress is saved, and you can pick up where you left off any time.'],
    cta: ['See plans', L.pricing],
  },
  'access.revoked': {
    subject: 'Your access has ended',
    lines: [`Assalāmu ʿalaykum${name},`, p.reason === 'refunded' ? 'Your refund has been processed and your access has ended.' : 'Your access has ended because the payment could not be completed.'],
    cta: ['See plans', L.pricing],
  },
}[body.type];
if (!copy) return [{ json: { status: 'accepted', type: body.type, dedupeKey: body.dedupeKey, email: { mode: 'skip' }, whatsapp: { send: false } } }];

const html = `<div style="font-family:Inter,Arial,sans-serif;background:#0F1829;padding:32px;color:#E2E8F0">
<div style="max-width:520px;margin:auto;background:#16213A;border-radius:16px;padding:28px">
<p style="color:#ED8C44;font-size:12px;font-weight:800;letter-spacing:.18em;text-transform:uppercase;margin:0 0 16px">Demo Academy</p>
${copy.lines.map((l) => `<p style="line-height:1.6;margin:0 0 12px">${l}</p>`).join('')}
<a href="${copy.cta[1]}" style="display:inline-block;margin-top:12px;background:#ED8C44;color:#0F1829;font-weight:700;padding:12px 20px;border-radius:14px;text-decoration:none">${copy.cta[0]}</a>
</div></div>`;
const text = `${copy.lines.join('\n\n')}\n\n${copy.cta[0]}: ${copy.cta[1]}`;

// 4) WhatsApp only for failed payments, only with opt-in, never during the student's night (21:00–08:00)
let whatsapp = { send: false };
if (body.type === 'payment.failed' && s.whatsapp && $env.WHATSAPP_TOKEN && $env.WHATSAPP_PHONE_NUMBER_ID) {
  let local = DateTime.now().setZone(tz);
  let sendAt = local;
  if (local.hour >= 21) sendAt = local.plus({ days: 1 }).set({ hour: 8, minute: 0, second: 0 });
  else if (local.hour < 8) sendAt = local.set({ hour: 8, minute: 0, second: 0 });
  whatsapp = {
    send: true,
    sendAt: sendAt.toUTC().toISO(),
    request: {
      messaging_product: 'whatsapp',
      to: s.whatsapp.replace(/^\+/, ''),
      type: 'template',
      template: {
        name: $env.WHATSAPP_TEMPLATE_PAYMENT_FAILED || 'payment_failed',
        language: { code: 'en' },
        components: [{ type: 'body', parameters: [{ type: 'text', text: s.firstName || 'there' }, { type: 'text', text: date(p.graceUntil) }] }],
      },
    },
  };
}

return [{
  json: {
    status: 'accepted',
    type: body.type,
    dedupeKey: body.dedupeKey,
    email: {
      mode: $env.RESEND_API_KEY ? 'resend' : 'dry_run',
      request: { from: $env.EMAIL_FROM || 'Demo Academy <onboarding@resend.dev>', to: [s.email], subject: copy.subject, html, text },
    },
    whatsapp,
  },
}];
